interface CartRepo {
    fun add(item: String)
    fun items(): List<String>
}

class FakeCartRepo : CartRepo {
    private val stored = mutableListOf<String>()
    var addCalls = 0
    override fun add(item: String) {
        addCalls++
        if (item !in stored) stored += item
    }
    override fun items() = stored.toList()
}

fun `given empty cart when same item added twice then stored once`() {
    val repo = FakeCartRepo()
    repo.add("apple"); repo.add("apple")
    println("${repo.items()} ${repo.addCalls}")
}

